'use strict';
(function(){
let active='repertoire';
const esc=I.esc;
function chooseTab(id,focus=false){if(!['repertoire','musicians','schedule'].includes(id))return;active=id;document.querySelectorAll('[data-rail-tab]').forEach(b=>{const on=b.dataset.railTab===id;b.classList.toggle('active',on);b.setAttribute('aria-selected',String(on));b.tabIndex=on?0:-1;if(on&&focus)b.focus();});document.querySelectorAll('[data-rail-panel]').forEach(p=>p.hidden=p.dataset.railPanel!==id);renderRail();}
function musicians(){return `<div class="rail-title"><h2>Les musiciens<span class="dot">.</span></h2><span>${state.people.length} / 6</span></div><div class="rail-scroll musician-list"><div class="page-items">${state.people.map(p=>`<article class="musician-summary"><span class="musician-summary-head">${avatar(p)}<span><strong>${p.name}</strong><small>${p.instrument} · ${p.style}</small></span></span>${I.vitals(p)}<span class="member-activity">${T.busy(state)?'♫':p.sleeping?'☾':actionIcon[p.action]} ${activity(p)} <small>· ${H.rooms[p.bedroomId].label}</small></span><span class="member-traits">${p.traits.map(t=>`<span>${t}</span>`).join('')}</span>${p.intent&&p.intent.until>state.tick?`<span class="member-intent">↗ ${esc(p.intent.label)}${p.intent.startTick>state.tick?' · demain':!p.intent.applied?' · en attente':''}</span>`:''}${p.lastResponse&&!p.lastResponse.accepted?`<span class="member-refusal">Refus · ${esc(p.lastResponse.reason)}</span>`:''}<div class="member-actions"><button data-open-person="${p.id}">Fiche ↗</button></div></article>`).join('')}</div></div>`;}
function publicHint(week,compact=false){const f=state.tour.active?.week===week?state.tour.active.forecast:T.forecast(state,week);return `<div class="audience-hint ${compact?'compact':''}"><span class="audience-label">${compact?'Public pressenti':esc(f.label)}</span><div class="audience-genres">${f.styles.map(g=>`<span>${I.genreIcon(g)}${esc(g)}</span>`).join('')}<span class="audience-unknown" title="D’autres goûts pourront être présents">?</span></div>${compact?'':`<small>${esc(f.uncertainty)}</small>`}</div>`;}
function preparation(){
 const p=globalThis.MaisonShowPreparation.project(state),o=state.journey?.selected;
 if(!p.selected)return '<section class="show-preparation"><h3>Avant le concert</h3><p>Choisis la destination pour connaître ses exigences et préparer le répertoire.</p></section>';
 if(p.active)return `<section class="show-preparation"><h3>${p.locked?'Répertoire emporté':'Jour du concert'}</h3><p>${esc(T.activity(state))} · ${p.ready.length} chanson(s) ${p.locked?'emportée(s)':'prête(s)'}. Les séances reprendront après le retour.</p>${p.checks.map(c=>`<p class="prep-check ${c.ok?'done':'todo'}">${c.ok?'✓':'○'} ${esc(c.label)}</p>`).join('')}<p class="prep-stage">Sur scène : ${p.onStage.map(esc).join(' ')}</p></section>`;
 return `<section class="show-preparation" aria-label="Préparation du concert"><div class="prep-heading"><h3>Avant le concert</h3><span class="prep-badge ${p.complete?'done':'todo'}">${p.complete?'Minimum prêt':'À préparer'}</span></div><p class="prep-deadline">${esc(p.deadline)}</p><ul class="prep-checklist">${p.checks.map(c=>`<li class="prep-check ${c.ok?'done':'todo'}"><span aria-hidden="true">${c.ok?'✓':'○'}</span><div><strong>${esc(c.label)}</strong><small>${esc(c.detail)}</small></div></li>`).join('')}</ul>${!p.complete?`<div class="prep-next"><h4>À avancer en priorité</h4>${p.candidates.length?p.candidates.map(x=>`<button class="prep-song" data-prep-song="${esc(x.id)}"><strong>${esc(x.title)} ↗</strong><span>${esc(x.genre)} · ${esc(x.label)}</span>${x.detail?`<small>${esc(x.detail)}</small>`:''}</button>`).join(''):'<p>Commence une composition, puis propose-la au groupe et répète-la.</p>'}${p.candidateCount>3?`<small>${p.candidateCount-3} autre(s) chanson(s) dans le répertoire.</small>`:''}</div>`:'<p class="prep-note">Le minimum est prêt. Plus de chansons offrent davantage de possibilités sur scène.</p>'}<button data-prep-repertoire="all">Ouvrir le répertoire ↗</button><div class="prep-stage"><h4>À réussir sur scène</h4>${p.onStage.map(t=>`<p>◇ ${esc(t)}</p>`).join('')}<small>La préparation ne garantit pas la victoire.</small></div><p class="prep-affinity">${p.matching} chanson(s) prête(s) dans les styles annoncés : ${o.styles.map(esc).join(' · ')}. Une aide, pas une obligation.</p></section>`;
}
function schedule(){
 const j=state.journey,o=j?.selected,week=W.week(state),current=T.month(state),next=T.nextShowWeek(state),ended=j&&j.status!=='active',a=state.tour.active;
 return `<div class="schedule-now"><div><strong>Semaine ${week}</strong><span>${j?'Acte '+(j.act+1)+'/4 · ':''}${j?.chances??3}/3 chances</span></div></div><div class="rail-scroll calendar-scroll"><div class="calendar-content">${ended?window.MaisonJourneyUI.summary():`<section class="schedule-hero"><small>${a?'CONCERT EN COURS':'PROCHAIN SPECTACLE'} · S${next}</small><h3>${esc(o?.name||'Destination à choisir')}</h3>${a?`<p>${esc(T.activity(state))}</p>`:`<div class="countdown">${next===week?'Cette semaine':Math.max(0,next-week)+' <small>semaine'+(next-week>1?'s':'')+'</small>'}</div><small>${Math.max(0,next-week)} jour(s) simulé(s) avant la semaine du concert</small>`}${o?`<p>${o.fans} spectateurs · résistance ${o.resistance} %</p><p>✦ ${esc(o.rewardDescription)}</p>`:''}<button data-journey-open>${o?'Voir le parcours':'Choisir la destination'} ↗</button>${a?'<button id="openOngoingShow">Voir le show ↗</button>':''}</section>${preparation()}<small class="calendar-act">${j?esc(globalThis.MaisonJourney.currentAct(state).name):'Le parcours'}</small><div class="schedule-steps">${(globalThis.MaisonJourney?.currentAct(state)?.stages||[[],[],[]]).map((_,i)=>`<div class="schedule-step ${i===j?.stage?'current':''}"><span>${i<j?.stage?'✓':i+1} · ${['Première étape','Affirmer son style','Finale de l’acte'][i]}</span><b>${j?'S'+globalThis.MaisonJourney.stageWeek(state,i):'À venir'}</b></div>`).join('')}</div>${[current,current+1,current+2].map(m=>`<section class="mini-month"><h3>Mois ${m}</h3><div class="mini-weeks">${[1,2,3,4].map(n=>{const w=(m-1)*4+n;return `<span class="mini-week ${w===week?'now':''} ${T.scheduled(state,w)?'show':''}">S${w}${T.scheduled(state,w)?' ♫':''}</span>`;}).join('')}</div></section>`).join('')}`}${state.tour.completed.length?`<div class="past-shows"><h3>Derniers shows</h3>${state.tour.completed.slice(-2).reverse().map(x=>`<button data-show-history="${x.week}">S${x.week}<span>${esc(x.result.title)} ↗</span></button>`).join('')}</div>`:''}</div></div>`;
}
function renderRail(){if(active==='musicians'){const scroll=$('#musiciansPanel').querySelector('.rail-scroll')?.scrollTop||0;$('#musiciansPanel').innerHTML=musicians();$('#musiciansPanel').querySelector('.rail-scroll').scrollTop=scroll;$('#musiciansPanel').querySelectorAll('[data-open-person]').forEach(b=>b.onclick=()=>showPerson(b.dataset.openPerson));}if(active==='schedule'){const scroll=$('#schedulePanel').querySelector('.rail-scroll')?.scrollTop||0;$('#schedulePanel').innerHTML=schedule();$('#schedulePanel').querySelector('.rail-scroll').scrollTop=scroll;if($('#openOngoingShow'))$('#openOngoingShow').onclick=()=>{if(T.blocking(state))window.MaisonTourUI.showCurrent();else toast(T.activity(state)+'. Le temps se contrôle avec le bouton lecture/pause.');};$('#schedulePanel').querySelectorAll('[data-journey-open]').forEach(b=>b.onclick=()=>window.MaisonJourneyUI.open());$('#schedulePanel').querySelectorAll('[data-prep-song]').forEach(b=>b.onclick=()=>window.MaisonMusicUI.showSong(b.dataset.prepSong));$('#schedulePanel').querySelectorAll('[data-prep-repertoire]').forEach(b=>b.onclick=()=>chooseTab('repertoire',true));$('#schedulePanel').querySelectorAll('[data-show-history]').forEach(b=>b.onclick=()=>window.MaisonTourUI.showHistory(Number(b.dataset.showHistory)));}window.MaisonViewport?.schedule();document.querySelectorAll('[data-rail-tab]').forEach(b=>b.classList.toggle('show-due',b.dataset.railTab==='schedule'&&(T.isShowWeek(state)||T.busy(state))));}
document.querySelectorAll('[data-rail-tab]').forEach(b=>{b.onclick=()=>chooseTab(b.dataset.railTab);b.onkeydown=e=>{const tabs=['repertoire','musicians','schedule'];let index=tabs.indexOf(active);if(e.key==='ArrowRight')index=(index+1)%3;else if(e.key==='ArrowLeft')index=(index+2)%3;else if(e.key==='Home')index=0;else if(e.key==='End')index=2;else return;e.preventDefault();chooseTab(tabs[index],true);};});
window.MaisonRailUI={render:renderRail,chooseTab,resetView:()=>chooseTab('repertoire')};chooseTab('repertoire');
})();
